let currentFormal: FormalState = { reviewQueue: null, reports: [], trustify: null };
let refreshCurrentFormal: () => Promise<void> = async () => undefined;
let currentAnalysis: AnalysisState = { timeline: [], graph: null, transactions: [], alerts: [], processingRuns: [], auditLog: [], claims: [], contradictions: [], crossCaseLinks: [] };
let refreshCurrentAnalysis: () => Promise<void> = async () => undefined;
